// ---------- Shop sections (v4.62) ----------
// Avatar Decorations, Avatar Masks and Themes are sorted into sections in the Shop, instead of one "Animated / Not
// Animated" split that left half the page empty. Staff pick an item's section in the Owner panel, when publishing it or
// later in its editor (a built-in item's section is saved as an override, like its price). Built-in items start in the
// sections below, and anything without one goes in "More".
const SHOP_SECTIONED = ['decorations', 'masks', 'themes'];
const SHOP_SECTION_ORDER = {
  decorations: ['Hats & Crowns', 'Ears & Horns', 'All Around'],
  masks: ['Masks'],
  themes: ['Neon', 'Warm', 'Cool', 'Nature', 'Dark & Space'],
};
const shopSectionMap = groups => Object.fromEntries(Object.entries(groups).flatMap(([sec, ids]) => ids.map(id => [id, sec])));
const SHOP_SECTION_DEFAULTS = {
  decorations: shopSectionMap({
    'Hats & Crowns': ['halo', 'crown', 'party-hat', 'flower-crown', 'bow'],
    'Ears & Horns': ['cat-ears', 'devil-horns'],
    'All Around': ['sparkle-ring', 'angel-wings', 'headphones', 'pocket-blackhole'],
  }),
  themes: shopSectionMap({
    Neon: ['disco', 'synthwave', 'toxic', 'neonpink', 'neonblue', 'neonorange', 'cyber', 'holographic', 'candy', 'infrared', 'matrix', 'terminal'],
    Warm: ['sunset', 'blood', 'lava', 'gold', 'copper', 'amber', 'wine', 'coffee', 'fire', 'rust', 'coral', 'bloodmoon', 'solar'],
    Cool: ['ocean', 'arctic', 'ice', 'storm', 'steel', 'aqua', 'deepsea', 'midnight'],
    Nature: ['forest', 'emerald', 'mint', 'aurora', 'cherry', 'rose', 'sakura'],
    'Dark & Space': ['blackhole', 'supernova', 'eclipse', 'nebula', 'crimsonrift', 'plasma', 'galaxy', 'void', 'obsidian', 'purplerain', 'violet', 'lavender', 'ash'],
  }),
};
const cleanSectionName = s => (typeof s === 'string' ? s.replace(/[<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, 30) : '');
function shopSectionOf(key, item) {
  return cleanSectionName(item && item.section) || (SHOP_SECTION_DEFAULTS[key] || {})[item && item.id] || (key === 'masks' ? 'Masks' : 'More');
}
// The sections a list of items is in: the built-in order first, then any staff-made ones A to Z, and "More" last.
function shopSectionsFor(key, items) {
  const order = SHOP_SECTION_ORDER[key] || [];
  const used = [...new Set(items.map(i => shopSectionOf(key, i)))];
  const extra = used.filter(s => !order.includes(s)).sort((a, b) => (a === 'More') - (b === 'More') || a.localeCompare(b));
  return [...order.filter(s => used.includes(s)), ...extra];
}

function hexToRgbTuple(hex) {
  let h = hex.replace('#', '');
  if (h.length === 3) h = h.split('').map(c => c + c).join('');
  const n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function hexToRgbaStr(hex, a) { const [r, g, b] = hexToRgbTuple(hex); return `rgba(${r},${g},${b},${a})`; }
function lightenHex(hex, amt) { const [r, g, b] = hexToRgbTuple(hex); const f = v => Math.min(255, v + amt).toString(16).padStart(2, '0'); return `#${f(r)}${f(g)}${f(b)}`; }
function darkenHex(hex, amt) { const [r, g, b] = hexToRgbTuple(hex); const f = v => Math.max(0, v - amt).toString(16).padStart(2, '0'); return `#${f(r)}${f(g)}${f(b)}`; }
// The same color made no brighter than maxY (relative brightness, 0 to 1). Some themes' last color is bright since v4.71
// (request 82), and text boxes are made from it, so this keeps them as dark as the brightest ones were before.
function dimHexTo(hex, maxY) {
  const lin = v => { v /= 255; return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
  const out = v => Math.round(255 * (v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055)).toString(16).padStart(2, '0');
  const c = hexToRgbTuple(hex).map(lin), y = 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
  return y <= maxY ? hex : '#' + c.map(v => out(v * maxY / y)).join('');
}

// Applies (or clears) a Shop theme on top of whatever Settings > Themes
// preference is active — Shop themes are a separate, independent layer,
// so switching back to "no theme" here just falls back to that untouched.
function applyShopTheme(themeId) {
  const body = document.body;
  // These overrides live on <body> itself, not <html> — they used to be
  // on <html>, which seemed right ("inline style beats a class
  // selector") but was wrong for a different reason: --bg-deepest etc.
  // are also set by body.theme-light/ash/onyx below, and for CSS custom
  // properties, whichever element is CLOSEST to the elements actually
  // reading the property wins the inheritance, regardless of inline vs.
  // class — body is closer than html is. So with any Settings theme
  // other than Dark active (Dark adds no class to body at all), body's
  // own class-based value was silently shadowing the shop theme's
  // override before it ever reached anything inside body — shop themes
  // only ever worked while Dark was the active Settings theme. Setting
  // these directly on body puts them on the same element as those class
  // rules, so inline-beats-class actually applies like it's supposed to.
  const t = themeId ? shopThemeById(themeId) : null;
  // An equipped theme whose catalog entry hasn't loaded yet (custom themes
  // arrive from Firestore asynchronously) is left alone rather than reset —
  // subscribeCustomThemes re-applies once it knows about it.
  if (themeId && !t && !customThemesLoaded) return;
  const SHOP_ANIM_CLASSES = ['shop-anim-hue', 'shop-anim-holo', 'shop-anim-aurora', 'shop-anim-blackhole', 'shop-anim-supernova', 'shop-anim-eclipse', 'shop-anim-nebula', 'shop-anim-crimsonrift'];
  body.classList.remove(...SHOP_ANIM_CLASSES);
  if (!t) {
    ['--shop-theme-bg', '--bg-deepest', '--bg-secondary', '--bg-primary', '--bg-tertiary', '--bg-floating',
     '--bg-input', '--accent', '--accent-hover', '--accent-soft', '--text-link']
      .forEach(v => body.style.removeProperty(v));
    body.classList.remove('shop-theme-active');
    return;
  }
  body.classList.add('shop-theme-active');
  const [c1, c2, c3] = t.bg;
  body.style.setProperty('--shop-theme-bg', `linear-gradient(135deg, ${c1} 0%, ${c2} 55%, ${c3} 100%)`);
  // Panels normally paint a fully opaque color edge-to-edge with no gaps,
  // which sits in front of the ::before gradient layer above in paint
  // order and hid it completely — every shop theme, including the three
  // animated ones (hue-rotating Disco, Holographic, Aurora), was
  // rendering as a flat, static, unmoving color with zero visible
  // gradient or animation. Tested empirically: fully opaque panels showed
  // literally none of the gradient's third color stop, confirming it was
  // rendering but never visible. Making the panels translucent instead of
  // opaque lets it show through as a real, moving background wash — the
  // flat color still dominates (so text contrast barely changes) but the
  // gradient and its animation are now genuinely visible, which is the
  // entire point of paying for one of these.
  body.style.setProperty('--bg-deepest', hexToRgbaStr(c1, 0.62));
  body.style.setProperty('--bg-secondary', hexToRgbaStr(c1, 0.62));
  body.style.setProperty('--bg-tertiary', hexToRgbaStr(c1, 0.62));
  body.style.setProperty('--bg-floating', hexToRgbaStr(c1, 0.75));
  body.style.setProperty('--bg-primary', hexToRgbaStr(c2, 0.62));
  body.style.setProperty('--bg-input', hexToRgbaStr(lightenHex(dimHexTo(c3, 0.07), 12), 0.8));
  body.style.setProperty('--accent', t.accent);
  body.style.setProperty('--accent-hover', darkenHex(t.accent, 24));
  body.style.setProperty('--accent-soft', hexToRgbaStr(t.accent, 0.15));
  body.style.setProperty('--text-link', t.accent2 || t.accent);
  if (t.anim && SHOP_ANIM_CLASSES.includes('shop-anim-' + t.anim)) body.classList.add('shop-anim-' + t.anim);
}


// A generic registry tying each shop category to its catalog and the
// profile fields it reads/writes — lets the shop's render/buy/equip code
// stay generic instead of four near-identical copies of the same logic.
const SHOP_CATEGORY_DEFS = {
  decorations: { label: 'Avatar Decorations', get catalog() { return [...AVATAR_DECORATIONS, ...customDecorations.filter(d => !d.mask)]; }, ownedField: 'ownedDecorations', equipField: 'equippedDecoration' },
  // Full avatar masks are decorations flagged `mask` in the admin editor. They have their own
  // equip slot (equippedMask), so a mask and a decoration can be worn at the same time.
  masks: { label: 'Avatar Masks', get catalog() { return customDecorations.filter(d => d.mask); }, ownedField: 'ownedDecorations', equipField: 'equippedMask' },
  nameplates: { label: 'Nameplates', get catalog() { return [...NAMEPLATES, ...customNameplates]; }, ownedField: 'ownedNameplates', equipField: 'equippedNameplate' },
  profile_effects: { label: 'Profile Effects', get catalog() { return [...PROFILE_EFFECTS, ...customProfileEffects]; }, ownedField: 'ownedProfileEffects', equipField: 'equippedProfileEffect' },
  profile_frames: { label: 'Profile Frames', get catalog() { return [...PROFILE_FRAMES, ...customProfileFrames]; }, ownedField: 'ownedProfileFrames', equipField: 'equippedProfileFrame' },
  // Badges (v4.65): every one you own shows on your profile, next to the ones you earn, so there's nothing to equip
  badges: { label: 'Badges', get catalog() { return SHOP_BADGES; }, ownedField: 'ownedBadges', equipField: 'equippedBadge' },
  // (no "Animated" tag on themes since v4.62: the three with a moving background barely showed it, so the Owner had it removed)
  themes: { label: 'Themes', get catalog() { return [...SHOP_THEMES, ...customThemes]; }, ownedField: 'ownedThemes', equipField: 'equippedTheme' },
  banners: { label: 'Banners', get catalog() { return customBanners; }, ownedField: 'ownedBanners', equipField: 'equippedBanner' },
  music: { label: 'Music', get catalog() { return allMusicTracks(); }, ownedField: 'ownedMusic', equipField: 'equippedMusic' },
};
const PREMIUM_DURATION_MS = 3 * 24 * 60 * 60 * 1000; // 3 days
function isPremium(p) { return !!(p && p.premiumUntil && p.premiumUntil > Date.now()); }
function todayStr() { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }

