// ============================================================
// UPLOADS (images via Cloudinary, other files via Firebase Storage
// as a fallback — see the note at the top of this file about
// why Storage alone isn't enough anymore)
// ============================================================
function humanFileSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  const units = ['KB', 'MB', 'GB'];
  let i = -1;
  do { bytes /= 1024; i++; } while (bytes >= 1024 && i < units.length - 1);
  return bytes.toFixed(1) + ' ' + units[i];
}
// One upload to Cloudinary with live progress. A plain fetch() gives no progress and never times out, so a stuck upload just looked like
// it was "loading forever". This reports percent done, gives up if nothing moves for UPLOAD_STALL_MS, and passes on Cloudinary's own error.
const UPLOAD_STALL_MS = 45000, UPLOAD_PROCESS_MS = 180000;
function cloudinaryPost(endpoint, formData, onProgress, stallMs = UPLOAD_STALL_MS, processMs = UPLOAD_PROCESS_MS) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    let timer = null, sent = false;
    const arm = (ms, msg) => { clearTimeout(timer); timer = setTimeout(() => { xhr.abort(); reject(new Error(msg)); }, ms); };
    const stallMsg = 'The upload stopped moving, so it was cancelled. Check your connection and try again (big files can take a while).';
    xhr.open('POST', endpoint);
    xhr.upload.onprogress = (e) => {
      if (e.lengthComputable && onProgress) onProgress(Math.min(100, Math.round(e.loaded / e.total * 100)));
      arm(stallMs, stallMsg);
    };
    xhr.upload.onload = () => { sent = true; if (onProgress) onProgress(100); arm(processMs, 'Cloudinary took too long to process the file. Try a smaller file.'); };
    xhr.onerror = () => { clearTimeout(timer); reject(new Error('Could not reach Cloudinary. Check your connection and try again.')); };
    xhr.onabort = () => { clearTimeout(timer); };
    xhr.onload = () => {
      clearTimeout(timer);
      let data = null;
      try { data = JSON.parse(xhr.responseText); } catch (e) { /* not JSON */ }
      if (data) { resolve(data); return; }
      reject(new Error(xhr.status === 413 ? 'That file is too big to upload.' : `Cloudinary sent back an unexpected answer (${xhr.status}).`));
    };
    arm(stallMs, stallMsg);
    xhr.send(formData);
  });
}
async function uploadImageToCloudinary(file, onProgress) {
  if (!CLOUDINARY_CLOUD_NAME || CLOUDINARY_CLOUD_NAME === 'YOUR_CLOUD_NAME' || !CLOUDINARY_UPLOAD_PRESET || CLOUDINARY_UPLOAD_PRESET === 'YOUR_UPLOAD_PRESET') {
    throw new Error('Image uploads need a Cloudinary cloud name and unsigned upload preset added in script.js.');
  }
  const formData = new FormData();
  formData.append('file', file);
  formData.append('upload_preset', CLOUDINARY_UPLOAD_PRESET);
  const data = await cloudinaryPost(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/image/upload`, formData, onProgress);
  if (!data.secure_url) throw new Error((data.error && data.error.message) || 'Cloudinary upload failed.');
  return data.secure_url;
}
// Everything that isn't a picture (PDF, text, zip, Office files, audio, video...) goes to Cloudinary too, so file uploads work on the
// free plan with no Firebase Storage. Audio and video use Cloudinary's "video" upload type, everything else uses "raw".
// Free plan limits: 10 MB per file, 100 MB for video/audio.
const MAX_FILE_MB = 10, MAX_MEDIA_MB = 100;
const MEDIA_FILE_EXT = /\.(mp4|m4v|mov|webm|mkv|avi|mp3|wav|ogg|m4a|aac|flac)$/i;
function isMediaFile(file) { return /^(video|audio)\//.test(file.type || '') || MEDIA_FILE_EXT.test(file.name || ''); }
async function uploadFileToCloudinary(file, onProgress) {
  if (!CLOUDINARY_CLOUD_NAME || CLOUDINARY_CLOUD_NAME === 'YOUR_CLOUD_NAME' || !CLOUDINARY_UPLOAD_PRESET || CLOUDINARY_UPLOAD_PRESET === 'YOUR_UPLOAD_PRESET') {
    throw new Error('File uploads need a Cloudinary cloud name and unsigned upload preset added in script.js.');
  }
  const kind = isMediaFile(file) ? 'video' : 'raw';
  const safe = (file.name || 'file').replace(/[^a-zA-Z0-9._-]/g, '_');
  // For raw files the file name (with its extension) has to be part of the id, or the download comes back with no extension.
  const publicId = `uploads/${myUid}/${Date.now()}/${kind === 'raw' ? safe : safe.replace(/\.[^.]+$/, '')}`;
  const send = async (withId) => {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('upload_preset', CLOUDINARY_UPLOAD_PRESET);
    if (withId) formData.append('public_id', publicId);
    return cloudinaryPost(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/${kind}/upload`, formData, onProgress);
  };
  let data = await send(true);
  // If this Cloudinary account refuses our file name, send it again and let Cloudinary pick one.
  if (!data.secure_url && data.error && /unsupported|not allowed|public_id/i.test(data.error.message || '')) data = await send(false);
  if (!data.secure_url) {
    const msg = (data.error && data.error.message) || 'Cloudinary upload failed.';
    throw new Error(/too large|size/i.test(msg) ? `${file.name} is too big for the free Cloudinary plan.` : msg);
  }
  return data.secure_url;
}
async function uploadFileGeneric(file, isImage, onProgress) {
  return isImage ? uploadImageToCloudinary(file, onProgress) : uploadFileToCloudinary(file, onProgress);
}

// ---- staged attachments ----
// Files picked or pasted sit in a draft strip above the composer instead
// of sending instantly — lets you drop the wrong one and send several
// together as one message, matching how the real Discord client stages
// images before you hit send.
let draftAttachments = []; // { id, file, type: 'image'|'file', previewUrl }
// Chat upload limits (v4.56): regular accounts get 5 MB a file and 50 MB a video or song; Frixion Premium, Admins and
// Co-Owners the full 10 MB and 100 MB that Cloudinary's free plan allows; the Owner isn't checked here at all
// (Cloudinary still stops every file at its own 10 MB / 100 MB). A picture over the limit is shrunk to fit.
function uploadLimitMb(media) {
  const rank = sfMode ? 0 : platformRank(myProfile);
  if (rank >= 3) return Infinity;
  const big = rank >= 1 || isPremium(myProfile);
  return media ? (big ? MAX_MEDIA_MB : 50) : (big ? MAX_FILE_MB : 5);
}
// Redraws a picture smaller (as WebP, or JPEG where WebP can't be made) until it fits, so phone photos still send.
// GIFs (they'd stop moving) and pictures the browser can't open are left as they are.
async function shrinkImage(file, maxBytes) {
  if (file.size <= maxBytes || /gif$/i.test(file.type)) return file;
  let bmp;
  try { bmp = await createImageBitmap(file); } catch (e) { return file; }
  let scale = Math.min(1, 4096 / Math.max(bmp.width, bmp.height));
  for (let i = 0; i < 8; i++) {
    const c = document.createElement('canvas');
    c.width = Math.max(1, Math.round(bmp.width * scale)); c.height = Math.max(1, Math.round(bmp.height * scale));
    c.getContext('2d').drawImage(bmp, 0, 0, c.width, c.height);
    let blob = await new Promise(r => c.toBlob(r, 'image/webp', 0.85));
    if (!blob || blob.type !== 'image/webp') blob = await new Promise(r => c.toBlob(r, 'image/jpeg', 0.85));
    if (blob && blob.size <= maxBytes) return new File([blob], (file.name || 'image').replace(/\.[^.]+$/, '') + (blob.type === 'image/webp' ? '.webp' : '.jpg'), { type: blob.type });
    scale *= 0.75;
  }
  return file;
}
async function stageFile(file) {
  if (currentView !== 'channel' && currentView !== 'dm' && currentView !== 'groupdm') { toast('Pick a conversation first.'); return; }
  const isImage = file.type.startsWith('image/');
  const maxMb = uploadLimitMb(!isImage && isMediaFile(file));
  if (isImage && file.size > maxMb * 1024 * 1024) file = await shrinkImage(file, maxMb * 1024 * 1024);
  if (file.size > maxMb * 1024 * 1024) {
    const more = maxMb === 5 || maxMb === 50 ? ' Frixion Premium doubles it.' : '';   // (the regular limits)
    toast(`${file.name} is over ${maxMb} MB.${more}`, 'error');
    return;
  }
  draftAttachments.push({
    id: 'd' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
    file, type: isImage ? 'image' : 'file',
    previewUrl: isImage ? URL.createObjectURL(file) : null,
  });
  renderAttachmentDraft();
}
function removeDraftAttachment(id) {
  const idx = draftAttachments.findIndex(d => d.id === id);
  if (idx === -1) return;
  if (draftAttachments[idx].previewUrl) URL.revokeObjectURL(draftAttachments[idx].previewUrl);
  draftAttachments.splice(idx, 1);
  renderAttachmentDraft();
}
function clearDraftAttachments() {
  draftAttachments.forEach(d => { if (d.previewUrl) URL.revokeObjectURL(d.previewUrl); });
  draftAttachments = [];
  renderAttachmentDraft();
}
// ---- image viewer (Discord-style): click an image to open it fitted to the
// screen, click again to zoom bigger (pannable), click again to go back. ----
let imageViewerZoom = 0;
// Width (px) the picture takes when it is "fitted" to the screen.
function imageViewerFitWidth(img) {
  const nw = img.naturalWidth || 1, nh = img.naturalHeight || 1;
  const maxW = window.innerWidth * 0.92, maxH = window.innerHeight * 0.84;
  return Math.max(40, Math.round(nw * Math.min(maxW / nw, maxH / nh, 1)));
}
function imageViewerApplyWidths() {
  const img = $('image-preview-img');
  const fit = imageViewerFitWidth(img);
  img.style.setProperty('--fit-w', fit + 'px');
  // bigger = at least 2x the fitted size, or the natural size if that is larger
  img.style.setProperty('--zoom-w', Math.round(Math.max(img.naturalWidth || 0, fit * 2)) + 'px');
}
function setImageViewerZoom(level, animate = true) {
  imageViewerZoom = level;
  const box = $('image-preview-box');
  const scroller = $('image-preview-scroller');
  box.classList.toggle('no-anim', !animate);
  box.classList.toggle('zoom-1', level === 1);
  // keep the picture centred in the scroll area while its width animates
  const t0 = performance.now();
  const centre = () => {
    scroller.scrollLeft = (scroller.scrollWidth - scroller.clientWidth) / 2;
    scroller.scrollTop = (scroller.scrollHeight - scroller.clientHeight) / 2;
    if (level === 1 && performance.now() - t0 < 320) requestAnimationFrame(centre);
  };
  if (level === 1) requestAnimationFrame(centre); else { scroller.scrollLeft = 0; scroller.scrollTop = 0; }
}
function openImageViewer(url, name) {
  const img = $('image-preview-img');
  const modal = $('image-preview-modal');
  const box = $('image-preview-box');
  modal.classList.remove('closing');
  img.alt = name || 'Preview';
  img.onload = () => {
    imageViewerApplyWidths();
    // pop in from slightly smaller, like Discord
    box.classList.remove('opening'); void box.offsetWidth; box.classList.add('opening');
  };
  box.classList.remove('opening');
  box.classList.add('no-anim');
  box.classList.remove('zoom-1');
  imageViewerZoom = 0;
  img.src = url;
  if (img.complete && img.naturalWidth) img.onload();
  const open = $('image-preview-open');
  const web = /^https?:\/\//i.test(url || '');      // only real web addresses get an "Open original" link
  if (open) open.href = web ? url : '#';
  if (open) open.style.display = web ? '' : 'none';
  $('image-preview-copy').onclick = () => copyImage(url);
  openModal('image-preview-modal');
  requestAnimationFrame(() => requestAnimationFrame(() => box.classList.remove('no-anim')));
}
window.addEventListener('resize', () => {
  if (!$('image-preview-modal').classList.contains('hidden')) { $('image-preview-box').classList.add('no-anim'); imageViewerApplyWidths(); }
});
$('image-preview-img').addEventListener('click', e => {
  e.stopPropagation();
  setImageViewerZoom(imageViewerZoom === 0 ? 1 : 0);
});
// clicking the dark backdrop closes the viewer
$('image-preview-modal').addEventListener('click', e => {
  if (e.target === $('image-preview-modal')) closeModal('image-preview-modal');
});

// ---------- copying pictures (v4.58) ----------
// The clipboard only takes pictures as PNG, so the picture is drawn onto a canvas and copied from there (the places
// Frixion's pictures come from, Cloudinary, Discord and Tenor, all allow that). The copy starts right away, inside the
// click, with the picture following once it's ready, which Safari needs. A GIF copies as a still picture. If a picture
// can't be copied, its link is copied instead.
function imagePng(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    if (/^https?:/i.test(url)) img.crossOrigin = 'anonymous';
    img.onload = () => {
      try {
        const c = document.createElement('canvas');
        c.width = img.naturalWidth; c.height = img.naturalHeight;
        c.getContext('2d').drawImage(img, 0, 0);
        c.toBlob(b => (b ? resolve(b) : reject(new Error('empty'))), 'image/png');
      } catch (e) { reject(e); }
    };
    img.onerror = () => reject(new Error('load'));
    img.src = url;
  });
}
function copyImageLink(url, why) {
  navigator.clipboard.writeText(url).then(() => toast(why || 'Link copied.'), () => toast('Could not copy. Your browser blocked it.', 'error'));
}
function copyImage(url) {
  if (!url || !/^(https?:|data:image\/|blob:)/i.test(url)) return;
  const web = /^https?:/i.test(url);
  const fallback = () => (web ? copyImageLink(url, 'That picture can\'t be copied, so its link was copied instead.') : toast('Could not copy that picture.', 'error'));
  if (!window.ClipboardItem || !navigator.clipboard || !navigator.clipboard.write) { fallback(); return; }
  try {
    navigator.clipboard.write([new ClipboardItem({ 'image/png': imagePng(url) })]).then(() => toast('Image copied.'), fallback);
  } catch (e) { fallback(); }
}
// The computer app has no right-click menu of its own, so right-clicking a picture there shows this one (a browser
// already offers Copy Image in its own menu).
let imgMenu = null;
function closeImageMenu() { if (imgMenu) { imgMenu.remove(); imgMenu = null; } }
function showImageMenu(x, y, url) {
  closeImageMenu();
  const web = /^https?:/i.test(url);
  imgMenu = document.createElement('div');
  imgMenu.className = 'img-menu';
  imgMenu.innerHTML = '<button type="button" data-a="copy">Copy Image</button>'
    + (web ? '<button type="button" data-a="link">Copy Image Link</button><button type="button" data-a="open">Open Original</button>' : '');
  document.body.appendChild(imgMenu);
  const w = imgMenu.offsetWidth, h = imgMenu.offsetHeight;
  imgMenu.style.left = Math.max(4, Math.min(x, innerWidth - w - 4)) + 'px';
  imgMenu.style.top = Math.max(4, Math.min(y, innerHeight - h - 4)) + 'px';
  imgMenu.onclick = e => {
    const a = e.target.closest('button') && e.target.closest('button').dataset.a;
    if (!a) return;
    closeImageMenu();
    if (a === 'copy') copyImage(url);
    else if (a === 'link') copyImageLink(url);
    else if (a === 'open') window.open(url, '_blank', 'noopener');
  };
}
document.addEventListener('contextmenu', e => {
  closeImageMenu();
  if (!DESKTOP) return;
  const img = e.target.closest && e.target.closest('.msg-attachment img, #image-preview-img');
  if (img && !img.classList.contains('custom-emoji')) { e.preventDefault(); showImageMenu(e.clientX, e.clientY, img.currentSrc || img.src); return; }
  const items = textMenuItems(e.target);
  if (!items.length) return;
  e.preventDefault();
  showTextMenu(e.clientX, e.clientY, items);
});
// ---------- right-click menu for text in the computer app (v4.62) ----------
// The computer app has no right-click menu of its own (a browser has its own, so this only runs in the app): in a text
// box you get Cut, Copy, Paste and Select All; on selected text, Copy; on a message, Copy Text; on a link, Copy Link and
// Open Link. Pasting reads the clipboard (the app allows it); if it can't, the menu says to press Ctrl+V.
const isTextBox = el => el && (el.tagName === 'TEXTAREA' || (el.tagName === 'INPUT' && /^(text|search|url|email|tel|number|password|)$/i.test(el.type || '')));
function textMenuItems(target) {
  if (!target || !target.closest) return [];
  const box = target.closest('input, textarea, [contenteditable="true"]');
  const selText = String((window.getSelection && window.getSelection()) || '');
  if (box && (isTextBox(box) || box.isContentEditable)) {
    const ro = !!(box.readOnly || box.disabled);
    const hasSel = isTextBox(box) ? box.selectionStart !== box.selectionEnd : !!selText;
    return [
      ...(ro ? [] : [{ label: 'Cut', act: 'cut', off: !hasSel }]),
      { label: 'Copy', act: 'copy', off: !hasSel },
      ...(ro ? [] : [{ label: 'Paste', act: 'paste' }]),
      { label: 'Select All', act: 'all' },
    ].map(i => ({ ...i, box }));
  }
  const items = [];
  if (selText.trim()) items.push({ label: 'Copy', act: 'copysel', text: selText });
  const line = target.closest('.msg-line[data-mid]');
  const m = line && lastRawMessages.find(x => x.id === line.dataset.mid);
  if (m && m.text) items.push({ label: 'Copy Text', act: 'copytext', text: m.text });
  const a = target.closest('a[href]');
  const href = a && /^https?:\/\//i.test(a.href) ? a.href : '';
  if (href) items.push({ label: 'Copy Link', act: 'copytext', text: href }, { label: 'Open Link', act: 'open', text: href });
  return items;
}
function showTextMenu(x, y, items) {
  closeImageMenu();
  imgMenu = document.createElement('div');
  imgMenu.className = 'img-menu text-menu';
  imgMenu.innerHTML = items.map((it, i) => `<button type="button" data-i="${i}"${it.off ? ' disabled' : ''}>${esc(it.label)}</button>`).join('');
  document.body.appendChild(imgMenu);
  const w = imgMenu.offsetWidth, h = imgMenu.offsetHeight;
  imgMenu.style.left = Math.max(4, Math.min(x, innerWidth - w - 4)) + 'px';
  imgMenu.style.top = Math.max(4, Math.min(y, innerHeight - h - 4)) + 'px';
  imgMenu.addEventListener('mousedown', e => e.preventDefault());   // keep the text box focused and its selection where it is
  imgMenu.onclick = e => {
    const b = e.target.closest('button[data-i]');
    if (!b || b.disabled) return;
    const it = items[+b.dataset.i];
    closeImageMenu();
    runTextMenuItem(it);
  };
}
async function runTextMenuItem(it) {
  const box = it.box;
  if (it.act === 'copysel' || it.act === 'copytext') { copyText(it.text, it.act === 'copytext' && /^https?:/i.test(it.text) ? 'Link copied.' : 'Copied.'); return; }
  if (it.act === 'open') { window.open(it.text, '_blank', 'noopener'); return; }
  if (!box) return;
  box.focus();
  if (it.act === 'all') { if (isTextBox(box)) box.select(); else document.execCommand('selectAll'); return; }
  if (it.act === 'copy' || it.act === 'cut') {
    const text = isTextBox(box) ? box.value.slice(box.selectionStart, box.selectionEnd) : String(window.getSelection());
    if (!text) return;
    try { await navigator.clipboard.writeText(text); } catch (e) { document.execCommand('copy'); }
    if (it.act === 'cut') {
      if (isTextBox(box)) { box.setRangeText('', box.selectionStart, box.selectionEnd, 'end'); box.dispatchEvent(new Event('input', { bubbles: true })); }
      else document.execCommand('delete');
    }
    return;
  }
  if (it.act === 'paste') {
    let text = null;
    try { text = await navigator.clipboard.readText(); } catch (e) {}
    if (text == null) { if (!document.execCommand('paste')) toast('Press Ctrl+V to paste here.'); return; }
    if (!text) return;
    if (isTextBox(box)) { box.setRangeText(text, box.selectionStart, box.selectionEnd, 'end'); box.dispatchEvent(new Event('input', { bubbles: true })); }
    else document.execCommand('insertText', false, text);
  }
}
document.addEventListener('mousedown', e => { if (imgMenu && !imgMenu.contains(e.target)) closeImageMenu(); }, true);
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeImageMenu(); });
