function finishCommandMode() {
  const { cmd } = cmdMode, input = $('composer-input');
  cmdMode.values[cmdMode.active] = input.value;
  const vals = cmdMode.values.map(v => v.trim());
  const missing = cmd.options.findIndex((o, i) => o.required && !vals[i]);
  if (missing !== -1) {
    switchCommandOption(missing);
    toast(`Enter a ${cmd.options[missing].name} first.`);
    return null;
  }
  if (cmd.appCmd && !canHere('useApplicationCommands')) { toast('You do not have permission to use commands in this channel.', 'error'); return null; }
  let text;
  if (cmd.name === 'hyperlink') {
    const label = vals[0].replace(/[\[\]]/g, '');
    let url = vals[1];
    if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
    if (/\s/.test(url) || !/^https?:\/\/[^\s.\/]+\.[^\s]{2,}/i.test(url) || /[()<>"']/.test(url)) { switchCommandOption(1); toast('That link doesn\'t look right. Try something like https://example.com', 'error'); return null; }
    if (label.length > 120) { switchCommandOption(0); toast('Keep the message under 120 characters.', 'error'); return null; }
    if (url.length > 500) { switchCommandOption(1); toast('That link is too long.', 'error'); return null; }
    text = `[${label}](${url})`;
  } else if (cmd.name === 'purge') {
    if (vals[0] && !/^\d+$/.test(vals[0])) { switchCommandOption(0); toast('The count must be a whole number.', 'error'); return null; }
    text = vals[0] ? `/purge ${vals[0]}` : '/purge';
  } else if (cmd.name === 'mute' || cmd.name === 'ban' || cmd.name === 'kick') {
    const who = vals[0].replace(/^@/, '');
    if (/\s/.test(who)) { switchCommandOption(0); toast('Usernames do not contain spaces.', 'error'); return null; }
    text = `/${cmd.name} ${who}${vals[1] ? ' ' + vals[1] : ''}`;
  } else if (cmd.name === 'unmute' || cmd.name === 'unban') {
    const who = vals[0].replace(/^@/, '');
    if (/\s/.test(who)) { switchCommandOption(0); toast('Usernames do not contain spaces.', 'error'); return null; }
    text = `/${cmd.name} ${who}`;
  } else if (cmd.name === 'sfmode') {
    const v = vals[0].toLowerCase();
    if (v && !['on', 'off', 'toggle'].includes(v)) { switchCommandOption(0); toast('Use on, off or toggle, or leave it empty.', 'error'); return null; }
    text = v ? `/sfmode ${v}` : '/sfmode';
  } else if (cmd.name === 'tts') text = `/tts ${vals[0]}`;
  else if (cmd.name === 'spoiler') text = spoilerText(vals[0]);
  else if (cmd.name === 'raw') text = `/raw ${cmdMode.values[0].replace(/^\s+|\s+$/g, '')}`;
  else text = `/${cmd.name}`;
  exitCommandMode(false);
  return text;
}
// Keys for the list and command mode. Returns true when the key was used.
function slashHandleKey(e) {
  if (slashState) {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      const sc = $('slash-popup').querySelector('.slash-scroll'); renderSlashPopup.keep = sc ? sc.scrollTop : null;
      slashIndex = (slashIndex + (e.key === 'ArrowDown' ? 1 : slashCandidates.length - 1)) % slashCandidates.length;
      renderSlashPopup(); return true;
    }
    if (e.key === 'Tab' || e.key === 'Enter') { selectSlashCommand(slashCandidates[slashIndex]); return true; }
    if (e.key === 'Escape') { closeSlashPopup(); return true; }
    return false;
  }
  if (cmdMode) {
    if (e.key === 'Escape') { exitCommandMode(); return true; }
    if (e.key === 'Tab' && cmdMode.cmd.options.length) { switchCommandOption((cmdMode.active + (e.shiftKey ? -1 : 1) + cmdMode.cmd.options.length) % cmdMode.cmd.options.length); return true; }
    if (e.key === 'Backspace') return commandBackspaceOnEmpty(e.target);
  }
  return false;
}

let mentionState = null;      // { el, start, query } — start is the index of "@" in el.value
let mentionCandidates = [];
let mentionSelectedIndex = 0;

function updateMentionState(el) {
  const pos = el.selectionStart;
  if (pos == null) { closeMentionPopup(); return; }
  const before = el.value.slice(0, pos);
  const m = /(?:^|\s)@([A-Za-z0-9_]{0,24})$/.exec(before);
  if (!m) { closeMentionPopup(); return; }
  const query = m[1];
  const start = pos - query.length - 1;
  const lowerQ = query.toLowerCase();
  const candidates = currentContextUsernames()
    .filter(u => u && u.toLowerCase().startsWith(lowerQ))
    .sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()))
    .slice(0, 6);
  if (!candidates.length) { closeMentionPopup(); return; }
  mentionState = { el, start, query };
  mentionCandidates = candidates;
  mentionSelectedIndex = 0;
  renderMentionPopup();
}
function closeMentionPopup() {
  mentionState = null; mentionCandidates = []; mentionSelectedIndex = 0;
  $('mention-popup').classList.add('hidden');
}
function positionMentionPopup(el) {
  const popup = $('mention-popup');
  const fRect = el.getBoundingClientRect();
  const off = measureCaretOffset(el);
  popup.style.left = Math.max(8, Math.min(fRect.left + off.x - (el.scrollLeft || 0), window.innerWidth - popup.offsetWidth - 8)) + 'px';
  popup.style.bottom = (window.innerHeight - fRect.top + 8) + 'px';
}
function renderMentionPopup() {
  const popup = $('mention-popup');
  popup.innerHTML = mentionCandidates.map((u, i) => {
    const p = profileCache[u] || { username: u, avatarColor: '#5865f2' };
    return `<div class="mention-row${i === mentionSelectedIndex ? ' selected' : ''}" data-idx="${i}">
      ${avatarHTML(22, p.avatarColor, initials(p.username), null, p.avatarUrl)}
      <span class="mention-row-name">${esc(p.username)}</span>
      ${u === myUid ? '<span class="mention-row-you">you</span>' : ''}
    </div>`;
  }).join('') + `<div class="mention-hint">Tab to autofill</div>`;
  popup.classList.remove('hidden');
  popup.querySelectorAll('.mention-row').forEach(row => {
    row.onclick = () => completeMention(mentionCandidates[+row.dataset.idx]);
  });
  positionMentionPopup(mentionState.el);
}
function completeMention(username) {
  if (!mentionState || username == null) return;
  const { el, start, query } = mentionState;
  const before = el.value.slice(0, start);
  const after = el.value.slice(start + 1 + query.length);
  const insertion = '@' + username + ' ';
  el.value = before + insertion + after;
  el.selectionStart = el.selectionEnd = before.length + insertion.length;
  closeMentionPopup();
  autoResize(el);
  ckFireInput(el);
  if (ckField && ckField.el === el) positionCkCursor();
}
document.addEventListener('click', (e) => {
  if (!mentionState) return;
  if (e.target.closest('#mention-popup') || e.target.closest('#composer-input')) return;
  closeMentionPopup();
});

