  if (k === 'gdm') return (window.__myGroupDMs || []).map(g => ({ id: g.id, label: groupDMDisplayName(g) }));
  if (k === 'server') return (window.__myServers || []).map(s => ({ id: s.id, label: s.name || 'Server' }));
  if (k === 'game') return qoGameChoices();
